+function updateUI(){ $('cash').textContent=money(game.cash);$('speed').textContent=Math.round(game.speed);$('gear').textContent=game.speed<1?'N':game.speed<22?'1':game.speed<43?'2':'3';$('distanceLeft').textContent=Math.max(0,Math.ceil(game.distanceTotal-game.distance))+' km';$('progressText').textContent=Math.min(100,Math.floor(game.distance/game.distanceTotal*100))+'%';$('progressBar').style.width=Math.min(100,game.distance/game.distanceTotal*100)+'%';$('conditionText').textContent=Math.round(game.condition)+'%';$('conditionBar').style.width=game.condition+'%';$('fuelFill').style.width=game.fuel+'%';$('fuelText').textContent=Math.round(game.fuel)+'%';$('qualityText').textContent=Math.round(game.quality)+'%';$('qualityFill').style.width=game.quality+'%';$('driveBtn').innerHTML=game.running?'Ⅱ &nbsp; ENGINE RUNNING':'▶ &nbsp; START YOUR ENGINE';$('driveBtn').classList.toggle('secondary',game.running);$('conditionBar').style.background=game.condition<35?'#e56b56':'#b4d86c';$('timer').textContent=String(Math.floor(game.seconds/60)).padStart(2,'0')+':'+String(Math.floor(game.seconds%60)).padStart(2,'0');$('tripText').textContent=game.trip;$('routeName').textContent=game.trip.replace(' → ',' → ');$('cargoName').textContent=game.cargo;$('cargoTag').textContent=game.cargoTag;$('reward').textContent='₹'+money(game.reward);$('locationText').textContent=game.distance<30?'Khandala Ghat':game.distance<75?'Lonavala Highway':'Panvel Approach';$('weatherText').textContent=game.weather+(game.weather==='CLEAR'?' · 28°C':' · 24°C');$('engineLevel').textContent=game.engine?'Tune '+game.engine:'Stock';$('tuneBtn').textContent=game.engine>=3?'MAX LEVEL':'UPGRADE · ₹'+(game.engine+1)*3000;$('tuneBtn').disabled=game.engine>=3||game.cash<(game.engine+1)*3000;}
+function resize(){const r=canvas.getBoundingClientRect(),d=Math.min(devicePixelRatio||1,2);canvas.width=Math.max(1,Math.floor(r.width*d));canvas.height=Math.max(1,Math.floor(r.height*d));ctx.setTransform(d,0,0,d,0,0)}
+window.addEventListener('resize',resize);resize();
+function poly(points,fill){ctx.fillStyle=fill;ctx.beginPath();ctx.moveTo(points[0][0],points[0][1]);for(let i=1;i<points.length;i++)ctx.lineTo(points[i][0],points[i][1]);ctx.closePath();ctx.fill()}
