+function drawScene(now){const w=canvas.clientWidth,h=canvas.clientHeight;if(!w||!h)return;ctx.clearRect(0,0,w,h);const t=now/1000, horizon=h*.38, center=w*.5+game.laneVisual*w*.13;const sky=ctx.createLinearGradient(0,0,0,horizon);sky.addColorStop(0,game.weather==='RAIN'?'#6e8586':'#87b6bd');sky.addColorStop(.7,game.weather==='RAIN'?'#b3c1b6':'#eab77e');sky.addColorStop(1,'#e7c68b');ctx.fillStyle=sky;ctx.fillRect(0,0,w,horizon+2);
+// sun and layered Western Ghats
